using System;using System.Net;using System.Net.Http;using System.Reflection;using System.Text;
class Program{
 static readonly Type Proxy=typeof(HttpClient).Assembly.GetType("System.Net.Http.HttpEnvironmentProxy"),Credentials=typeof(HttpClient).Assembly.GetType("System.Net.Http.HttpEnvironmentProxyCredentials");
 static readonly MethodInfo Parse=Proxy.GetMethod("GetUriFromString",BindingFlags.Static|BindingFlags.NonPublic),ParseCredential=Credentials.GetMethod("GetCredentialsFromString",BindingFlags.Static|BindingFlags.NonPublic),TryCredentials=Credentials.GetMethod("TryCreate",BindingFlags.Static|BindingFlags.Public);
 static string D(string s){if(s=="~")return null;var b=new StringBuilder();if(s!="-")for(int i=0;i<s.Length;i+=4)b.Append((char)Convert.ToInt32(s.Substring(i,4),16));return b.ToString();}static string H(string s){if(s==null)return "~";if(s.Length==0)return "-";var b=new StringBuilder();foreach(char c in s)b.Append(((int)c).ToString("x4"));return b.ToString();}
 static string Error(Exception e){while(e is TargetInvocationException t)e=t.InnerException;return e.GetType().FullName+":"+unchecked((uint)e.HResult).ToString("x8")+":"+H(e.Message)+":"+(e is ArgumentException a?H(a.ParamName):"~");}
 static string Snapshot(Uri u)=>u==null?"null":H(u.OriginalString)+"/"+H(u.Scheme)+"/"+H(u.Host)+"/"+u.Port+"/"+H(u.UserInfo)+"/"+H(u.AbsoluteUri)+"/"+H(u.ToString());
 static string Credential(NetworkCredential c)=>c==null?"null":(ReferenceEquals(c,CredentialCache.DefaultNetworkCredentials)?"D":"N")+":"+H(c.UserName)+":"+H(c.Password)+":"+H(c.Domain);
 static Uri UriOf(string s){var value=D(s);return value==null?null:new Uri(value,UriKind.RelativeOrAbsolute);}
 static void Main(){string line;while((line=Console.ReadLine())!=null){var a=line.Split(' ');try{if(a[0]=="E"){
 var names=new[]{"http_proxy","HTTP_PROXY","https_proxy","HTTPS_PROXY","all_proxy","ALL_PROXY","no_proxy","NO_PROXY","GATEWAY_INTERFACE"};foreach(var key in names)Environment.SetEnvironmentVariable(key,null);for(int i=0;i<names.Length;i++){var value=D(a[i+1]);if(value!=null)Environment.SetEnvironmentVariable(names[i],value);}
 var values=new object[]{null};var created=(bool)Proxy.GetMethod("TryCreate",BindingFlags.Public|BindingFlags.Static).Invoke(null,values);if(!created){Console.WriteLine("null");continue;}var proxy=(IWebProxy)values[0];var request=UriOf(a[10]);var target=proxy.GetProxy(request);Console.WriteLine(Snapshot(target)+":"+(proxy.IsBypassed(request)?"1":"0")+":"+Credential(proxy.Credentials?.GetCredential(target,null)));continue;
}if(a[0]=="G"){Console.WriteLine(char.IsDigit(D(a[1])[0])?"1":"0");continue;}if(a[0]=="U"){Console.WriteLine(Snapshot((Uri)Parse.Invoke(null,new object[]{D(a[1])})));continue;}if(a[0]=="Q"){Console.WriteLine(UriOf(a[1]).Equals(UriOf(a[2]))?"1":"0");continue;}if(a[0]=="C"){Console.WriteLine(Credential((NetworkCredential)ParseCredential.Invoke(null,new object[]{D(a[1])})));continue;}if(a[0]=="K"){var c=(ICredentials)TryCredentials.Invoke(null,new object[]{UriOf(a[1]),UriOf(a[2])});Console.WriteLine(Credential(c?.GetCredential(UriOf(a[3]),null)));continue;}if(a[0]=="P"){var http=(Uri)Parse.Invoke(null,new object[]{D(a[1])});var https=(Uri)Parse.Invoke(null,new object[]{D(a[2])});if(http==null&&https==null){Console.WriteLine("null");continue;}var constructor=Proxy.GetConstructors(BindingFlags.Instance|BindingFlags.NonPublic)[0];var p=(IWebProxy)constructor.Invoke(new object[]{http,https,D(a[3])});var request=UriOf(a[4]);Console.WriteLine(Snapshot(p.GetProxy(request))+":"+(p.IsBypassed(request)?"1":"0"));continue;}throw new Exception("Unknown mode");}catch(Exception e){Console.WriteLine(Error(e));}}}
}
